@namespace sv_6cf119116b864a998c430826201aac1d.Components.Pages.Apply

<div class="d-flex justify-content-between align-items-center mb-4">
    @for (int i = 0; i < StepNames.Length; i++)
    {
        var stepIndex = i;
        var isCurrent = stepIndex == CurrentStep;
        var isCompleted = stepIndex < CurrentStep;
        var isFuture = stepIndex > CurrentStep;

        <div class="text-center flex-fill position-relative">
            @if (stepIndex > 0)
            {
                <div class="step-connector @(isCompleted || isCurrent ? "active" : "")"></div>
            }
            <div class="step-circle @(isCurrent ? "current" : isCompleted ? "completed" : "future")"
                 role="button"
                 @onclick="() => OnStepClick(stepIndex)">
                @if (isCompleted)
                {
                    <span>&#10003;</span>
                }
                else
                {
                    <span>@(stepIndex + 1)</span>
                }
            </div>
            <div class="step-label @(isFuture ? "text-muted" : "")">
                @StepNames[stepIndex]
            </div>
        </div>
    }
</div>

@code {
    private static readonly string[] StepNames = { "Personal Info", "Work History", "References", "Cover Letter", "Review & Submit" };

    [Parameter] public int CurrentStep { get; set; }
    [Parameter] public EventCallback<int> OnStepClicked { get; set; }

    private async Task OnStepClick(int step)
    {
        if (step < CurrentStep)
        {
            await OnStepClicked.InvokeAsync(step);
        }
    }
}

.step-circle {
    width: 40px;
    height: 40px;
    border-radius: 50%;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    font-weight: bold;
    margin-bottom: 0.5rem;
    transition: all 0.2s;
}

.step-circle.current {
    background-color: #0d6efd;
    color: white;
    box-shadow: 0 0 0 3px rgba(13, 110, 253, 0.25);
}

.step-circle.completed {
    background-color: #198754;
    color: white;
    cursor: pointer;
}

.step-circle.completed:hover {
    background-color: #146c43;
}

.step-circle.future {
    background-color: #e9ecef;
    color: #6c757d;
}

.step-label {
    font-size: 0.8rem;
    font-weight: 500;
}

.step-connector {
    position: absolute;
    top: 20px;
    left: -50%;
    right: 50%;
    height: 3px;
    background-color: #e9ecef;
    z-index: -1;
}

.step-connector.active {
    background-color: #198754;
}

@namespace sv_6cf119116b864a998c430826201aac1d.Components.Pages.Apply

<div class="card p-3 mb-3">
    <div class="d-flex justify-content-between align-items-center mb-2">
        <h6 class="mb-0">Position @(Index + 1)</h6>
        @if (ShowRemove)
        {
            <button type="button" class="btn btn-sm btn-outline-danger" @onclick="OnRemove">Remove</button>
        }
    </div>

    <div class="row g-3">
        <div class="col-md-6">
            <label class="form-label">Company Name *</label>
            <input type="text" class="form-control" value="@Entry.Company"
                   @onchange="e => Update(Entry with { Company = (string?)e.Value ?? "" })" />
        </div>
        <div class="col-md-6">
            <label class="form-label">Job Title *</label>
            <input type="text" class="form-control" value="@Entry.Title"
                   @onchange="e => Update(Entry with { Title = (string?)e.Value ?? "" })" />
        </div>
        <div class="col-md-4">
            <label class="form-label">Start Date *</label>
            <input type="date" class="form-control" value="@Entry.StartDate.ToString("yyyy-MM-dd")"
                   @onchange="e => Update(Entry with { StartDate = DateTime.Parse((string?)e.Value ?? DateTime.Today.ToString("yyyy-MM-dd")) })" />
        </div>
        <div class="col-md-4">
            <label class="form-label">End Date</label>
            <input type="date" class="form-control" value="@(Entry.EndDate?.ToString("yyyy-MM-dd") ?? "")"
                   disabled="@IsCurrent"
                   @onchange="e => Update(Entry with { EndDate = string.IsNullOrEmpty((string?)e.Value) ? null : DateTime.Parse((string)e.Value) })" />
        </div>
        <div class="col-md-4 d-flex align-items-end">
            <div class="form-check">
                <input class="form-check-input" type="checkbox" checked="@IsCurrent"
                       @onchange="e => ToggleCurrent((bool?)e.Value ?? false)" />
                <label class="form-check-label">Currently working here</label>
            </div>
        </div>
        <div class="col-12">
            <label class="form-label">Description</label>
            <textarea class="form-control" rows="3" value="@Entry.Description"
                      @onchange="e => Update(Entry with { Description = (string?)e.Value ?? "" })"></textarea>
        </div>
    </div>
</div>

@code {
    [Parameter, EditorRequired] public WorkEntry Entry { get; set; } = default!;
    [Parameter] public int Index { get; set; }
    [Parameter] public bool ShowRemove { get; set; }
    [Parameter] public EventCallback<WorkEntry> OnEntryChanged { get; set; }
    [Parameter] public EventCallback OnRemove { get; set; }

    private bool IsCurrent => Entry.EndDate == null && Entry.StartDate != default;

    private void ToggleCurrent(bool isCurrent)
    {
        if (isCurrent)
            Update(Entry with { EndDate = null });
        else
            Update(Entry with { EndDate = DateTime.Today });
    }

    private async Task Update(WorkEntry updated)
    {
        await OnEntryChanged.InvokeAsync(updated);
    }
}

@namespace sv_6cf119116b864a998c430826201aac1d.Components.Pages.Apply

<div class="card p-3 mb-3">
    <h6>Reference @(Index + 1)</h6>
    <div class="row g-3">
        <div class="col-md-6">
            <label class="form-label">Name *</label>
            <input type="text" class="form-control" value="@Reference.Name"
                   @onchange="e => Update(Reference with { Name = (string?)e.Value ?? "" })" />
        </div>
        <div class="col-md-6">
            <label class="form-label">Relationship *</label>
            <input type="text" class="form-control" value="@Reference.Relationship"
                   @onchange="e => Update(Reference with { Relationship = (string?)e.Value ?? "" })" />
        </div>
        <div class="col-md-6">
            <label class="form-label">Email *</label>
            <input type="email" class="form-control" value="@Reference.Email"
                   @onchange="e => Update(Reference with { Email = (string?)e.Value ?? "" })" />
        </div>
        <div class="col-md-6">
            <label class="form-label">Phone</label>
            <input type="tel" class="form-control" value="@Reference.Phone"
                   @onchange="e => Update(Reference with { Phone = (string?)e.Value ?? "" })" />
        </div>
    </div>
    @if (ShowRemove)
    {
        <div class="mt-2">
            <button type="button" class="btn btn-sm btn-outline-danger" @onclick="OnRemove">Remove</button>
        </div>
    }
</div>

@code {
    [Parameter, EditorRequired] public Reference Reference { get; set; } = default!;
    [Parameter] public int Index { get; set; }
    [Parameter] public bool ShowRemove { get; set; }
    [Parameter] public EventCallback<Reference> OnReferenceChanged { get; set; }
    [Parameter] public EventCallback OnRemove { get; set; }

    private async Task Update(Reference updated)
    {
        await OnReferenceChanged.InvokeAsync(updated);
    }
}

