@namespace sv_6cf119116b864a998c430826201aac1d.Components.Pages.Apply

<h4>Cover Letter</h4>

<div class="mb-3">
    <label class="form-label">Write your cover letter below</label>
    <textarea class="form-control" rows="12" @oninput="OnInput" value="@CoverLetterText"></textarea>
    <div class="form-text text-end">
        @CoverLetterText.Length / @MaxLength characters
    </div>
</div>

<div class="d-flex justify-content-between">
    <button class="btn btn-secondary" @onclick="OnBack">Back</button>
    <button class="btn btn-primary" @onclick="HandleNext">Next</button>
</div>

@code {
    private const int MaxLength = 2000;

    [Parameter] public string? InitialText { get; set; }
    [Parameter] public EventCallback<string> OnNext { get; set; }
    [Parameter] public EventCallback OnBack { get; set; }

    private string CoverLetterText = "";

    protected override void OnParametersSet()
    {
        if (InitialText is not null)
        {
            CoverLetterText = InitialText;
        }
    }

    private void OnInput(ChangeEventArgs e)
    {
        var text = (string?)e.Value ?? "";
        if (text.Length <= MaxLength)
            CoverLetterText = text;
    }

    private async Task HandleNext()
    {
        await OnNext.InvokeAsync(CoverLetterText);
    }
}

