@namespace sv_6cf119116b864a998c430826201aac1d.Components.Pages.Apply

<div class="card p-3 mb-3">
    <div class="d-flex justify-content-between align-items-center mb-2">
        <h6 class="mb-0">Position @(Index + 1)</h6>
        @if (ShowRemove)
        {
            <button type="button" class="btn btn-sm btn-outline-danger" @onclick="OnRemove">Remove</button>
        }
    </div>

    <div class="row g-3">
        <div class="col-md-6">
            <label class="form-label">Company Name *</label>
            <input type="text" class="form-control" value="@Entry.Company"
                   @onchange="OnCompanyChanged" />
        </div>
        <div class="col-md-6">
            <label class="form-label">Job Title *</label>
            <input type="text" class="form-control" value="@Entry.Title"
                   @onchange="OnTitleChanged" />
        </div>
        <div class="col-md-4">
            <label class="form-label">Start Date *</label>
            <input type="date" class="form-control" value="@StartDateStr"
                   @onchange="OnStartDateChanged" />
        </div>
        <div class="col-md-4">
            <label class="form-label">End Date</label>
            <input type="date" class="form-control" value="@EndDateStr"
                   disabled="@IsCurrent"
                   @onchange="OnEndDateChanged" />
        </div>
        <div class="col-md-4 d-flex align-items-end">
            <div class="form-check">
                <input class="form-check-input" type="checkbox" checked="@IsCurrent"
                       @onchange="OnCurrentToggled" />
                <label class="form-check-label">Currently working here</label>
            </div>
        </div>
        <div class="col-12">
            <label class="form-label">Description</label>
            <textarea class="form-control" rows="3" value="@Entry.Description"
                      @onchange="OnDescriptionChanged"></textarea>
        </div>
    </div>
</div>

@code {
    [Parameter, EditorRequired] public WorkEntry Entry { get; set; } = default!;
    [Parameter] public int Index { get; set; }
    [Parameter] public bool ShowRemove { get; set; }
    [Parameter] public EventCallback<WorkEntry> OnEntryChanged { get; set; }
    [Parameter] public EventCallback OnRemove { get; set; }

    private bool IsCurrent => Entry.EndDate == null;
    private string StartDateStr => Entry.StartDate.ToString("yyyy-MM-dd");
    private string EndDateStr => Entry.EndDate?.ToString("yyyy-MM-dd") ?? string.Empty;

    private Task OnCompanyChanged(ChangeEventArgs e) =>
        OnEntryChanged.InvokeAsync(Entry with { Company = (string?)e.Value ?? string.Empty });

    private Task OnTitleChanged(ChangeEventArgs e) =>
        OnEntryChanged.InvokeAsync(Entry with { Title = (string?)e.Value ?? string.Empty });

    private Task OnStartDateChanged(ChangeEventArgs e)
    {
        if (DateTime.TryParse((string?)e.Value, out var date))
            return OnEntryChanged.InvokeAsync(Entry with { StartDate = date });
        return Task.CompletedTask;
    }

    private Task OnEndDateChanged(ChangeEventArgs e)
    {
        var val = (string?)e.Value;
        var endDate = string.IsNullOrEmpty(val) ? (DateTime?)null : DateTime.Parse(val);
        return OnEntryChanged.InvokeAsync(Entry with { EndDate = endDate });
    }

    private Task OnCurrentToggled(ChangeEventArgs e)
    {
        var isCurrent = (bool?)e.Value ?? false;
        if (isCurrent)
            return OnEntryChanged.InvokeAsync(Entry with { EndDate = null });
        else
            return OnEntryChanged.InvokeAsync(Entry with { EndDate = DateTime.Today });
    }

    private Task OnDescriptionChanged(ChangeEventArgs e) =>
        OnEntryChanged.InvokeAsync(Entry with { Description = (string?)e.Value ?? string.Empty });
}

